<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700&family=Source+Sans+3:wght@400;600;700&display=swap" rel="stylesheet">
<style>
:root{--ink:#e5e7eb;--muted:#9ca3af;--line:#263244;--blue:#2563eb;--pale:#eff6ff;--green:#10b981;--red:#dc2626;--bg:#0b1120}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:'Source Sans 3',sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}
.layout{min-height:100vh;display:grid;grid-template-columns:245px 1fr}.sidebar{background:#111827;color:#e5e7eb;padding:26px 18px;display:flex;flex-direction:column;gap:30px}.brand{font:700 25px 'Bricolage Grotesque',sans-serif;color:white;padding:0 12px}.brand span{color:#60a5fa}.nav-label{color:#9ca3af;text-transform:uppercase;letter-spacing:1.3px;font-size:12px;padding:0 12px}.nav a{display:flex;align-items:center;gap:12px;padding:12px;border-radius:10px;color:#cbd5e1;text-decoration:none;margin:4px 0}.nav a.active,.nav a:hover{background:#263449;color:white}.nav .ico{width:22px;text-align:center}.sidebar-note{margin-top:auto;color:#9ca3af;font-size:13px;line-height:1.5;padding:12px}
main{min-width:0;padding:28px 34px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:28px}.eyebrow{color:var(--blue);font-weight:700;text-transform:uppercase;letter-spacing:1.2px;font-size:12px}.topbar h1{font:700 clamp(26px,3vw,34px) 'Bricolage Grotesque',sans-serif;margin:4px 0}.top-desc{color:var(--muted);margin:0}.admin-chip{background:#111827;border:1px solid var(--line);border-radius:999px;padding:9px 14px;font-weight:700;white-space:nowrap}
.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-bottom:24px}.stat{background:#111827;border:1px solid var(--line);border-radius:16px;padding:18px 20px;box-shadow:0 8px 24px #00000020}.stat-top{display:flex;justify-content:space-between;align-items:center;color:var(--muted);font-size:14px}.stat-icon{display:grid;place-items:center;background:var(--pale);color:var(--blue);border-radius:10px;width:38px;height:38px;font-size:19px}.stat strong{display:block;font:700 28px 'Bricolage Grotesque',sans-serif;margin-top:10px}
.panel{background:#111827;border:1px solid var(--line);border-radius:16px;box-shadow:0 8px 24px #00000020;overflow:hidden}.panel-head{padding:20px 22px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap}.panel-head h2{font:700 21px 'Bricolage Grotesque',sans-serif;margin:0}.tools{display:flex;gap:10px;flex-wrap:wrap}.search{min-width:220px}.search,input,select,textarea{border:1px solid #374151;border-radius:9px;padding:10px 12px;background:#111827;color:var(--ink);outline:none}.search:focus,input:focus,select:focus,textarea:focus{border-color:var(--blue);box-shadow:0 0 0 3px #2563eb1c}.btn{border:0;border-radius:9px;padding:10px 15px;font-weight:700;display:inline-flex;align-items:center;justify-content:center;gap:8px}.btn-primary{background:var(--blue);color:white}.btn-primary:hover{background:#1d4ed8}.btn-secondary{background:#1f2937;color:#d1d5db}.btn-danger{background:#fef2f2;color:var(--red)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:760px}th{text-align:left;font-size:12px;text-transform:uppercase;letter-spacing:.8px;color:var(--muted);background:#0f172a;padding:13px 20px}td{padding:15px 20px;border-top:1px solid #263244;vertical-align:middle}tbody tr:hover{background:#131e30}.product-cell{display:flex;align-items:center;gap:12px;min-width:230px}.thumb{width:52px;height:52px;border-radius:11px;background:linear-gradient(135deg,#1e293b,#263b59);display:grid;place-items:center;color:var(--blue);font-size:23px;overflow:hidden;flex-shrink:0}.thumb img{width:100%;height:100%;object-fit:cover}.p-name{font-weight:700}.p-sku{font-size:12px;color:var(--muted)}.pill{display:inline-block;padding:4px 9px;border-radius:999px;font-size:12px;font-weight:700}.in-stock{background:#d1fae5;color:#047857}.low-stock{background:#fef3c7;color:#92400e}.out-stock{background:#fee2e2;color:#b91c1c}.actions{display:flex;gap:7px}.icon-btn{border:1px solid var(--line);background:#111827;border-radius:8px;padding:7px 9px}.icon-btn:hover{background:#1f2937}.empty{text-align:center;padding:45px 20px;color:var(--muted)}.table-foot{padding:14px 20px;border-top:1px solid var(--line);color:var(--muted);font-size:13px;display:flex;justify-content:space-between;gap:10px}
.modal-backdrop{position:fixed;inset:0;background:#0f172acc;display:none;align-items:center;justify-content:center;padding:20px;z-index:10}.modal-backdrop.show{display:flex}.modal{background:#111827;width:min(620px,100%);max-height:92vh;overflow:auto;border-radius:18px;box-shadow:0 25px 80px #0008}.modal-head{padding:20px 24px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.modal-head h2{margin:0;font:700 22px 'Bricolage Grotesque',sans-serif}.close{border:0;background:#1f2937;border-radius:8px;padding:6px 10px;font-size:20px}.form{padding:22px 24px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field{display:flex;flex-direction:column;gap:6px}.field.full{grid-column:1/-1}.field label{font-size:13px;font-weight:700;color:#d1d5db}.field input,.field select,.field textarea{width:100%}.field textarea{min-height:78px;resize:vertical}.form-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.toast{position:fixed;right:22px;bottom:22px;background:#111827;color:white;padding:13px 18px;border-radius:10px;box-shadow:0 8px 25px #0002;display:none;z-index:20}.toast.show{display:block}.mobile-menu{display:none}
@media(max-width:900px){.layout{grid-template-columns:1fr}.sidebar{padding:16px;gap:14px}.nav{display:flex;flex-wrap:wrap}.nav-label,.sidebar-note{display:none}.nav a{margin:0}.brand{padding:0}.sidebar{gap:12px}main{padding:22px 16px}.stats{gap:10px}.stat{padding:14px}.search{min-width:180px}}
@media(max-width:560px){.topbar{align-items:flex-start;flex-direction:column}.stats{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.panel-head{align-items:stretch}.tools{width:100%}.search{width:100%;min-width:0}.tools .btn{flex:1}.table-foot{flex-direction:column}}
</style>